            btn.Font = new System.Drawing.Font("Segoe UI", 9.5F, System.Drawing.FontStyle.Regular);
            btn.ForeColor = System.Drawing.Color.Gainsboro;
            btn.Padding = new System.Windows.Forms.Padding(10, 0, 0, 0);
            btn.Size = new System.Drawing.Size(238, 42);
            btn.TabIndex = tabIndex;
            btn.Text = text;
            btn.TextAlign = System.Drawing.ContentAlignment.MiddleLeft;
            btn.UseVisualStyleBackColor = true;
            btn.Cursor = System.Windows.Forms.Cursors.Hand;
        }

